package com.focusflow.api.service; import com.focusflow.api.dto.ApiDtos.*; import com.focusflow.api.entity.AppUser; import com.focusflow.api.repository.UserRepository; import com.focusflow.api.security.JwtService; import org.springframework.http.HttpStatus; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.web.server.ResponseStatusException; @Service public class AuthService { final UserRepository users;final PasswordEncoder enc;final JwtService jwt; public AuthService(UserRepository u,PasswordEncoder e,JwtService j){users=u;enc=e;jwt=j;} public Auth register(Register r){if(users.existsByEmailIgnoreCase(r.email()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Email already registered");var u=new AppUser();u.name=r.name();u.email=r.email().toLowerCase();u.password=enc.encode(r.password());users.save(u);return new Auth(jwt.create(u.id,u.email),u.name,u.email);} public Auth login(Login r){var u=users.findByEmailIgnoreCase(r.email()).filter(x->enc.matches(r.password(),x.password)).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid email or password"));return new Auth(jwt.create(u.id,u.email),u.name,u.email);} }
